package com.acely.document;
import com.fasterxml.jackson.databind.JsonNode; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/api/documents") @CrossOrigin(origins="http://localhost:5173") public class DocumentController { private final DocumentService service; public DocumentController(DocumentService s){service=s;}
 @PostMapping(value="/upload",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public Map<String,Object> upload(@RequestParam("file") MultipartFile file)throws Exception{Document d=service.upload(file);return summary(d);}
 @GetMapping public List<Map<String,Object>> list(){return service.all().stream().map(this::summary).toList();} @GetMapping("/{id}") public Map<String,Object> get(@PathVariable long id){return summary(service.get(id));} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable long id){service.delete(id);}
 @PostMapping("/{id}/generate") public Map<String,Object> generateAll(@PathVariable long id){service.generateAll(id);return summary(service.get(id));} @PostMapping("/{id}/generate/{type}") public JsonNode generate(@PathVariable long id,@PathVariable String type){return service.generate(id,type);} @GetMapping("/{id}/{type:notes|flashcards|quiz|mindmap}") public ResponseEntity<JsonNode> resource(@PathVariable long id,@PathVariable String type){JsonNode node=service.resource(id,type);return node==null?ResponseEntity.noContent().build():ResponseEntity.ok(node);}
 private Map<String,Object> summary(Document d){return Map.of("documentId",d.id,"fileName",d.fileName,"fileType",d.fileType,"fileSize",d.fileSize,"status",d.status,"uploadedAt",d.uploadedAt,"notesAvailable",d.notesJson!=null,"flashcardsAvailable",d.flashcardsJson!=null,"quizAvailable",d.quizJson!=null,"mindMapAvailable",d.mindMapJson!=null);}
}
